def check_k_square(r, constant_term=486, leading_coeff=64):
    # We are checking 64 * k_n^2 = constant_term * (1 - r^n)
    # Assuming a_0 = -486 (constant term of Q_C(x))

    # Check n=1
    rhs_n1 = constant_term * (1 - r)
    if rhs_n1 < 0:
        # Need k_n^2 >= 0
        return None, "Negative RHS"

    if rhs_n1 % leading_coeff != 0:
        return None, "Not divisible by 64"

    k_sq_n1 = rhs_n1 // leading_coeff
    if k_sq_n1 < 0:
         return None, "Negative k^2"

    k_n1 = k_sq_n1**0.5
    if k_n1 == int(k_n1):
        return int(k_n1), "Found integer k_1"
    else:
        return None, "Not a perfect square"

# Test for integer ratios r >= 2
results = {}
for r in range(2, 10):
    k, reason = check_k_square(r)
    results[r] = (k, reason)

print("--- Checking n=1 for Q_C(x) = 64x^2 - 486 ---")
for r, (k, reason) in results.items():
    print(f"Ratio r={r}: k_1={k}, Reason={reason}")
